 internal void ShowCaptureButton(){if(captureButton!=null&&!captureButton.IsDisposed){captureButton.TopMost=store.Pref.WidgetTop;captureButton.Show();return;}LoadWidgetImage();captureButton=new CaptureWidget{Text="Jago Capture",FormBorderStyle=FormBorderStyle.None,Size=new Size(52,52),StartPosition=FormStartPosition.Manual,Location=new Point(Screen.PrimaryScreen.WorkingArea.Right-80,Screen.PrimaryScreen.WorkingArea.Bottom-120),TopMost=store.Pref.WidgetTop,ShowInTaskbar=false,BackColor=Color.FromArgb(72,109,110)};using(var path=new GraphicsPath()){path.AddEllipse(0,0,52,52);captureButton.Region=new Region(path);}captureButton.Location=WidgetPosition(new Point(store.Pref.WidgetX,store.Pref.WidgetY));Point origin=Point.Empty,screen=Point.Empty;bool moved=false;captureButton.MouseDown+=(s,e)=>{if(e.Button==MouseButtons.Left){origin=e.Location;screen=Cursor.Position;moved=false;}};captureButton.MouseMove+=(s,e)=>{if(e.Button==MouseButtons.Left&&!store.Pref.WidgetLocked&&(moved||Math.Abs(Cursor.Position.X-screen.X)+Math.Abs(Cursor.Position.Y-screen.Y)>5)){moved=true;captureButton.Location=new Point(Cursor.Position.X-origin.X,Cursor.Position.Y-origin.Y);}};captureButton.MouseUp+=(s,e)=>{if(e.Button==MouseButtons.Left){if(moved){captureButton.Location=WidgetPosition(captureButton.Location);store.Pref.WidgetX=captureButton.Left;store.Pref.WidgetY=captureButton.Top;store.SavePrefs();}else BeginCapture("region");}};captureButton.Paint+=(s,e)=>{e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(widgetImage!=null){e.Graphics.InterpolationMode=InterpolationMode.HighQualityBicubic;e.Graphics.DrawImage(widgetImage,4,4,44,44);return;}using(var p=new Pen(Color.FromArgb(248,246,240),3)){e.Graphics.DrawRectangle(p,12,15,28,22);e.Graphics.DrawEllipse(p,20,20,12,12);e.Graphics.DrawLine(p,16,12,25,12);}};var menu=new ContextMenuStrip();menu.Items.Add("Capture region",null,(s,e)=>BeginCapture("region"));menu.Items.Add("Capture active window",null,(s,e)=>BeginCapture("active"));menu.Items.Add("Capture & annotate",null,(s,e)=>BeginCapture("edit-region"));menu.Items.Add("Widget appearance…",null,(s,e)=>WidgetAppearance());menu.Items.Add("Lock position",null,(s,e)=>{store.Pref.WidgetLocked=!store.Pref.WidgetLocked;store.SavePrefs();});menu.Opening+=(s,e)=>{foreach(ToolStripMenuItem item in menu.Items)if(item.Text=="Lock position")item.Checked=store.Pref.WidgetLocked;};menu.Items.Add("Always on top",null,(s,e)=>{store.Pref.WidgetTop=!store.Pref.WidgetTop;captureButton.TopMost=store.Pref.WidgetTop;store.SavePrefs();});menu.Items.Add("Snap near screen edges",null,(s,e)=>{store.Pref.WidgetSnap=!store.Pref.WidgetSnap;store.SavePrefs();});menu.Opening+=(s,e)=>{foreach(ToolStripMenuItem item in menu.Items){if(item.Text=="Always on top")item.Checked=store.Pref.WidgetTop;if(item.Text=="Snap near screen edges")item.Checked=store.Pref.WidgetSnap;}};menu.Items.Add("Open notes",null,(s,e)=>ShowWindow());menu.Items.Add("Hide capture button",null,(s,e)=>ToggleCaptureButton());menu.Items.Add("Record video snippet…",null,(s,e)=>VideoSnippet());captureButton.ContextMenuStrip=menu;PreparePopup(menu);captureButton.Opacity=Math.Max(.3,store.Pref.WidgetOpacity/100.0);captureButton.FormClosed+=(s,e)=>{menu.Dispose();if(widgetImage!=null){widgetImage.Dispose();widgetImage=null;}};captureButton.Show();}
}

